program.compute:
options=read('/input/options')
from itertools import combinations
result=[]
for k in range(goal['min_count'],goal['max_count']+1):
 for combo in combinations(options,k):
  ids=[c['id'] for c in combo]
  owners=[c['owner'] for c in combo]
  if len(set(owners))!=len(owners):
   continue
  cost_sum=sum(c['cost'] for c in combo)
  quality_sum=sum(c['quality'] for c in combo)
  if cost_sum>goal['sum_bounds']['cost']['max']:
   continue
  if quality_sum<goal['sum_bounds']['quality']['min']:
   continue
  # Check requires closed dependencies
  requires_ok=True
  for c in combo:
   for r in c['requires']:
    if r not in ids:
     requires_ok=False
     break
   if not requires_ok:
    break
  if not requires_ok:
   continue
  # no_conflicts false means conflicts allowed
  # order by rank,id ascending
  sorted_combo=sorted(combo,key=lambda x:(x['rank'],x['id']))
  result=[c['id'] for c in sorted_combo]
  break
 if result:
  break

program.effects:
existing=read('/output/selection')
if existing and valid(existing):
 result=existing
else:
 write('/output/selection',result)
send('report','team',result)
if exists('/tmp/cache'):
 delete('/tmp/cache')

